import {GameObjects, Physics} from "phaser";
import type {SolarFlareData} from "../gameData/SolarFlareData.ts";
import Entity from "./Entity.ts";
import Player from "./Player.ts";
import Enemy from "./Enemy.ts";
import Health from "../components/Health.ts";
import GameConstants from "../GameConstants.ts";

// A wall of fire that crosses the whole arena along a band, like an asteroid belt but in one piece.
// The path is shown during a warning phase. The player takes damage when touching the bright front,
// enemies die. The visual is a gradient texture generated by code (no image needed)
export default class SolarFlare extends GameObjects.Sprite {
    private static readonly TEXTURE_KEY: string = 'solarflare';
    private static readonly TEXTURE_WIDTH: number = 256;
    private static readonly TEXTURE_HEIGHT: number = 64;
    // Distance (px) between the arena border and the flare when it waits and when it disappears
    private static readonly BORDER_MARGIN: number = 100;

    private readonly _data: SolarFlareData;
    private readonly _direction: { x: number, y: number };
    private readonly _bandWidth: number;
    private readonly _player: Player;
    private readonly _enemies: Physics.Arcade.Group;
    private readonly _onPlayerHit: (damage: number) => void;
    private readonly _warning: GameObjects.Rectangle;
    private readonly _travelLength: number;
    private _elapsed: number = 0;
    private _travelled: number = 0;
    private _launched: boolean = false;

    // direction: the way the flare travels. bandStart / bandWidth: the band, along the axis perpendicular to it
    constructor(scene: Phaser.Scene, data: SolarFlareData, direction: { x: number, y: number },
                bandStart: number, bandWidth: number, player: Player, enemies: Physics.Arcade.Group,
                onPlayerHit: (damage: number) => void) {
        super(scene, 0, 0, '__DEFAULT');

        SolarFlare.ensureTexture(scene);
        this.setTexture(SolarFlare.TEXTURE_KEY);

        this._data = data;
        this._direction = direction;
        this._bandWidth = bandWidth;
        this._player = player;
        this._enemies = enemies;
        this._onPlayerHit = onPlayerHit;

        // Waits beyond the arena border: the camera is bound to the arena, so the player never sees it coming
        const crossCenter: number = bandStart + bandWidth / 2;
        const margin: number = data.thickness / 2 + SolarFlare.BORDER_MARGIN;
        if (direction.x !== 0) {
            this.setPosition(direction.x > 0 ? -margin : GameConstants.ARENA_WIDTH + margin, crossCenter);
            this._travelLength = GameConstants.ARENA_WIDTH + margin * 2;
            this._warning = scene.add.rectangle(GameConstants.ARENA_WIDTH / 2, crossCenter,
                GameConstants.ARENA_WIDTH, bandWidth, 0xff3300, 0.2);
        } else {
            this.setPosition(crossCenter, direction.y > 0 ? -margin : GameConstants.ARENA_HEIGHT + margin);
            this._travelLength = GameConstants.ARENA_HEIGHT + margin * 2;
            this._warning = scene.add.rectangle(crossCenter, GameConstants.ARENA_HEIGHT / 2,
                bandWidth, GameConstants.ARENA_HEIGHT, 0xff3300, 0.2);
        }

        // The texture is bright on its right edge: rotated so that this edge leads the way.
        // Local width = thickness (along the direction), local height = band width
        this.setDisplaySize(data.thickness, bandWidth);
        this.setRotation(Math.atan2(direction.y, direction.x));
        this.setBlendMode(Phaser.BlendModes.ADD).setDepth(9);
        scene.add.existing(this);

        // Warning zone: pulsing, over the whole path
        this._warning.setStrokeStyle(6, 0xff8800, 1).setDepth(7);
        scene.tweens.add({
            targets: this._warning, alpha: {from: 0.35, to: 1}, duration: 400, yoyo: true, repeat: -1
        });
    }

    destroy(fromScene?: boolean) {
        // Don't leave tweens running on destroyed objects
        this.scene?.tweens?.killTweensOf(this);
        this.scene?.tweens?.killTweensOf(this._warning);
        this._warning?.destroy();

        super.destroy(fromScene);
    }

    preUpdate(time: number, delta: number) {
        super.preUpdate(time, delta);

        this._elapsed += delta;
        if (this._elapsed < this._data.warningDuration)
            return;

        if (!this._launched) {
            this._launched = true;
            // The fire flickers while it travels
            this.scene.tweens.add({targets: this, alpha: {from: 0.8, to: 1}, duration: 90, yoyo: true, repeat: -1});
        }

        const step: number = this._data.speed * delta / 1000;
        this.x += this._direction.x * step;
        this.y += this._direction.y * step;
        this._travelled += step;

        this.hitTargets();

        if (this._travelled >= this._travelLength)
            this.destroy();
    }

    private hitTargets() {
        if (this._player.active && this.touches(this._player))
            this._onPlayerHit(this._data.damage);

        for (const child of this._enemies.getChildren()) {
            const enemy = child as Enemy;
            if (!enemy.active || !this.touches(enemy))
                continue;

            const health = enemy.getComponent(Health);
            health?.damage(health.max);
        }
    }

    // Is the target inside the band, within the deadly depth behind the front of the flare?
    private touches(target: Entity): boolean {
        const dx: number = target.x - this.x;
        const dy: number = target.y - this.y;
        // Position of the target along the direction (relative to the flare center) and across it
        const along: number = dx * this._direction.x + dy * this._direction.y;
        const across: number = -dx * this._direction.y + dy * this._direction.x;
        const radius: number = target.arcadeBody.halfWidth;

        const front: number = this._data.thickness / 2;
        return Math.abs(across) <= this._bandWidth / 2 + radius
            && along <= front + radius
            && along >= front - this._data.hitThickness - radius;
    }

    // Horizontal gradient: transparent tail on the left, bright front on the right, soft top and bottom edges
    private static ensureTexture(scene: Phaser.Scene) {
        if (scene.textures.exists(SolarFlare.TEXTURE_KEY))
            return;

        const width: number = SolarFlare.TEXTURE_WIDTH;
        const height: number = SolarFlare.TEXTURE_HEIGHT;
        const texture = scene.textures.createCanvas(SolarFlare.TEXTURE_KEY, width, height);
        if (!texture)
            return;

        const context = texture.getContext();
        const gradient = context.createLinearGradient(0, 0, width, 0);
        gradient.addColorStop(0, 'rgba(255, 60, 0, 0)');
        gradient.addColorStop(0.45, 'rgba(255, 90, 0, 0.25)');
        gradient.addColorStop(0.75, 'rgba(255, 160, 30, 0.7)');
        gradient.addColorStop(0.92, 'rgba(255, 220, 100, 1)');
        gradient.addColorStop(1, 'rgba(255, 255, 230, 1)');
        context.fillStyle = gradient;
        context.fillRect(0, 0, width, height);

        // Soft edges, thin enough to keep the hit zone fair
        context.globalCompositeOperation = 'destination-in';
        const edges = context.createLinearGradient(0, 0, 0, height);
        edges.addColorStop(0, 'rgba(0, 0, 0, 0)');
        edges.addColorStop(0.05, 'rgba(0, 0, 0, 1)');
        edges.addColorStop(0.95, 'rgba(0, 0, 0, 1)');
        edges.addColorStop(1, 'rgba(0, 0, 0, 0)');
        context.fillStyle = edges;
        context.fillRect(0, 0, width, height);

        texture.refresh();
    }
}
